public Character convertToType(Class<?> type, Object value) throws Exception {
    if (type.equals(Character.class)) {
        if (value instanceof Character) {
            return (Character) value;
        } else if (value instanceof String) {
            // Convert string to Character
            String strValue = (String) value;
            if (strValue.length() == 1) {
                return strValue.charAt(0);
            } else {
                throw new Exception("Cannot convert string '" + strValue + "' to Character");
            }
        } else if (value instanceof Number) {
            // Convert number to Character
            int intValue = ((Number) value).intValue();
            if (intValue >= 0 && intValue <= Character.MAX_VALUE) {
                return (char) intValue;
            } else {
                throw new Exception("Cannot convert number '" + value + "' to Character");
            }
        } else {
            // Cannot convert to Character
            throw new Exception("Cannot convert value '" + value + "' to Character");
        }
    } else {
        // Convert to Character and then convert to target type
        Character charValue = convertToType(Character.class, value);
        return convertToType(type, charValue);
    }
}

